/**
 * Driver pasted directly into Streamlabs' own Alert Box "Custom HTML/CSS/JS"
 * editor (one type/tier combination at a time, generated by control.html's
 * "Streamlabs Alert Box code" section). Streamlabs handles receiving the
 * Twitch event, queueing alerts, and controlling how long each stays on
 * screen; this file only has to render one event, once, using whatever
 * `{token}` values Streamlabs substituted into the pasted HTML before this
 * page loaded.
 *
 * Tier and layout variant aren't computed here: control.html bakes a fixed
 * `data-tier`/`data-variant` into each generated widget, so pasting, say,
 * the "Tip / Huge / Jar" output into its own Streamlabs Alert Box variation
 * and setting that variation's own condition (Streamlabs' own amount-based
 * routing, not anything in this file) is what decides which pasted widget
 * fires for a given event.
 *
 * There's no relay, socket, or token to manage here: Streamlabs re-renders
 * this HTML fresh for every alert and tears it down after, so there's
 * nothing left running between alerts that could need reconnecting.
 */
import { AlertStage } from "./components/AlertStage.js";

const DURATION = 5000;
const TOP_OFFSET = 96;

/**
 * The seven per-type Alert Box boxes Streamlabs exposes; `resub` and
 * `giftsub` both map to this repo's single `sub` `AlertType`.
 */
type StreamlabsAlertBoxType =
  "follow" | "sub" | "resub" | "giftsub" | "bits" | "raid" | "tip";

const fmt = (n: number): string =>
  String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ",");

/**
 * Reads one `[data-token]` span's text inside `#zw-tokens`. Streamlabs
 * leaves a token's literal `{name}`-shaped placeholder in place when it
 * doesn't apply to this alert type or the platform didn't supply a value,
 * so anything still shaped like `{...}` is treated as absent, not as data.
 */
function readToken(name: string): string {
  const el = document.querySelector<HTMLElement>(
    `#zw-tokens [data-token="${name}"]`,
  );
  const text = el?.textContent?.trim() ?? "";
  if (!text || /^\{.*\}$/.test(text)) {
    return "";
  }
  return text;
}

function readAvatar(): string | undefined {
  return readToken("profile_image") || readToken("img") || undefined;
}

function parseAmount(raw: string): number {
  const n = parseFloat(raw.replace(/[^0-9.]/g, ""));
  return isNaN(n) ? 0 : n;
}

function buildEvent(
  boxType: StreamlabsAlertBoxType,
  tier: AlertTier,
): AlertStageEvent {
  const name = readToken("name") || "someone";
  const avatar = readAvatar();
  const message = readToken("userMessage") || readToken("message") || undefined;
  // Streamlabs only fills this in when the streamer has set a custom
  // "Message Template" for this alert type in their own dashboard (unset
  // otherwise); when set, it's meant to replace the default one-liner
  // below it, that's the whole point of the streamer configuring it.
  const messageTemplate = readToken("messageTemplate") || undefined;

  if (boxType === "follow") {
    return {
      type: "follow",
      name,
      avatar,
      detail: messageTemplate || "just followed",
      tier,
    };
  }
  if (boxType === "sub") {
    return {
      type: "sub",
      name,
      avatar,
      message,
      detail: messageTemplate || "Tier 1 · 1 month",
      amount: "1",
      tier,
    };
  }
  if (boxType === "resub") {
    const months = parseAmount(readToken("amount")) || 1;
    return {
      type: "sub",
      name,
      avatar,
      message,
      headline: "Resub",
      detail:
        messageTemplate ||
        `Tier 1 · ${months} ${months === 1 ? "month" : "months"}`,
      amount: String(months),
      tier,
    };
  }
  if (boxType === "giftsub") {
    // Streamlabs gives no explicit anonymous/community flag for this type,
    // just {name} (substituted with "Anonymous", or left absent) and
    // {count}: an absent/"anonymous" name means an anonymous gifter, and a
    // count above 1 means a community gift (several subs at once, to no
    // one viewer in particular) rather than one gifted at a specific
    // viewer, the only two things distinguishing the four real gift
    // scenarios from each other with the data this type actually gets.
    const rawName = readToken("name");
    const isAnonymous = !rawName || /^anonymous$/i.test(rawName);
    const count = parseAmount(readToken("count")) || 1;
    const isCommunity = count > 1;
    return {
      type: "sub",
      name: isAnonymous ? "An anonymous gifter" : rawName,
      avatar: isAnonymous ? undefined : avatar,
      headline: isCommunity ? "Community gift" : "Gifted sub",
      detail: isCommunity
        ? `${count} subs gifted to the community`
        : "gifted a sub",
      amount: isCommunity ? `×${count}` : undefined,
      tier,
    };
  }
  if (boxType === "bits") {
    const amount = parseAmount(readToken("amount"));
    return {
      type: "bits",
      name,
      avatar,
      message,
      amount: `${fmt(amount)} bits`,
      detail: messageTemplate || "cheered",
      tier,
    };
  }
  if (boxType === "raid") {
    const party = parseAmount(readToken("count")) || 1;
    return {
      type: "raid",
      name,
      avatar,
      party,
      detail:
        messageTemplate ||
        `${party} ${party === 1 ? "mate in tow" : "mates in tow"}`,
      amount: String(party),
      headline: "Incoming raid",
      tier,
    };
  }
  const amount = parseAmount(readToken("amount"));
  return {
    type: "tip",
    name,
    avatar,
    message,
    amount: `$${amount}`,
    detail: messageTemplate || "chucked in",
    tier,
  };
}

const MAX_WAIT_MS = 3000;
const POLL_INTERVAL_MS = 100;

/**
 * Streamlabs doesn't guarantee `{name}` is already substituted into the DOM
 * the instant this script runs, only that it eventually is; a single
 * synchronous read can catch it too early and fall back to "someone" even
 * for a real, named event. Polls for up to MAX_WAIT_MS, well short of the
 * alert's own 5s duration. Logs unconditionally (not worth gating behind a
 * flag: Streamlabs hosts this in its own widget URL, not one the streamer
 * can append a query string to) so a failure like this is diagnosable from
 * whatever console the Streamlabs Interact window exposes.
 */
function render(startedAt = Date.now()): void {
  const tokens = document.getElementById("zw-tokens");
  const boxType = tokens?.dataset.alertType as
    StreamlabsAlertBoxType | undefined;
  const root = document.getElementById("root");
  if (!tokens || !boxType || !root) {
    console.error(
      "[zw] streamlabs-alertbox.js: missing #zw-tokens[data-alert-type] or #root",
    );
    return;
  }
  const nameEl = document.querySelector<HTMLElement>(
    '#zw-tokens [data-token="name"]',
  );
  const name = readToken("name");
  console.log("[zw]", {
    zwTokensCount: document.querySelectorAll('[id="zw-tokens"]').length,
    tokensOuterHTML: tokens.outerHTML,
    nameElFound: !!nameEl,
    nameElRawText: nameEl?.textContent,
    readTokenName: name,
  });
  if (!name && Date.now() - startedAt < MAX_WAIT_MS) {
    setTimeout(() => render(startedAt), POLL_INTERVAL_MS);
    return;
  }
  const tier = (tokens.dataset.tier as AlertTier | undefined) || "big";
  const variant = tokens.dataset.variant || undefined;
  const stage = new AlertStage(root, { top: TOP_OFFSET, onDone: () => {} });
  stage.show({ ...buildEvent(boxType, tier), variant }, DURATION);
}

render();
